        SkRole.SNACK_FRAME -> of(SkRole.ACCENT)
        SkRole.BADGE_WARNING -> 0xFFFF8000.toInt()
        SkRole.BADGE_ERROR -> 0xFFFF0000.toInt()
        SkRole.BADGE_TEXT -> of(SkRole.BACKGROUND)
        SkRole.PAGE_GROUND -> of(SkRole.BACKGROUND)
        SkRole.PAGE_TEXT -> of(SkRole.TEXT)
        SkRole.PAGE_ACCENT -> of(SkRole.ACCENT)
        SkRole.PAGE_FRAME -> mix(0.55f)
    }
